		(20, N'10,11', N'',       N'3', N'Mau3_HopDong_A1_2.doc',  N'HỢP ĐỒNG ĐÀO TẠO LÁI XE MÔ TÔ Hạng A1 - TP. Hồ Chí Minh', 1),
		(30, N'',      N'BCK,C1', N'4', N'Mau4_HopDong_B.doc',     N'HỢP ĐỒNG ĐÀO TẠO LÁI XE Ô TÔ', 1),
		(40, N'',      N'',       N'5', N'Mau5_HopDong_C1.doc',    N'HỢP ĐỒNG THANH LÝ', 1),
		(99, N'',      N'',       N'1', N'Mau1_HopDong_A1.doc',    N'HỢP ĐỒNG ĐÀO TẠO LÁI XE MÔ TÔ Hạng A1 - T. Gia Lai', 1)
