## 2. Code C# — thêm hàm match dùng chung

```csharp
#region Contract Template Rule

private DataTable dtbTemplateRule
{
    get
    {
        if (ViewState["dtbTemplateRule"] != null)
            return ViewState["dtbTemplateRule"] as DataTable;
        return null;
    }
    set { ViewState["dtbTemplateRule"] = value; }
}

private DataTable LoadTemplateRule()
{
    if (this.dtbTemplateRule == null)
    {
        SimsObject.SIM_Student obj = new SimsObject.SIM_Student();
        this.dtbTemplateRule = obj.GetDataTable("WEB_ContractTemplateRule_Search");
    }
    return this.dtbTemplateRule;
}

private bool IsInRuleList(string strList, string strValue)
{
    if (strList == null || strList.Trim() == "")
        return true; // rỗng = áp dụng mọi giá trị

    string[] arrValue = strList.Split(',');
    for (int i = 0; i < arrValue.Length; i++)
    {
        if (arrValue[i].Trim() == strValue)
            return true;
    }
    return false;
}

private DataRow GetTemplateRuleByCode(string strTemplateCode)
{
    DataTable dtbRule = LoadTemplateRule();
    if (dtbRule == null)
        return null;

    for (int i = 0; i < dtbRule.Rows.Count; i++)
    {
        if (dtbRule.Rows[i]["TemplateCode"].ToString() == strTemplateCode)
            return dtbRule.Rows[i];
    }
    return null;
}

private string ResolveTemplateCode(int intOfficeId, string strSpecialBranchId)
{
    DataTable dtbRule = LoadTemplateRule();
    if (dtbRule == null)
        return "1";

    for (int i = 0; i < dtbRule.Rows.Count; i++)
    {
        DataRow drwRule = dtbRule.Rows[i];

        // mẫu 5 (thanh lý) do người dùng tick chọn, không dùng để match tự động
        if (drwRule["TemplateCode"].ToString() == "5")
            continue;

        if (!IsInRuleList(drwRule["OfficeIDList"].ToString(), intOfficeId.ToString()))
            continue;
        if (!IsInRuleList(drwRule["SpecialBranchIDList"].ToString(), strSpecialBranchId))
            continue;

        return drwRule["TemplateCode"].ToString();
    }
    return "1";
}

#endregion
```

