private List<ContractTemplateRule> lstTemplateRule
{
    get
    {
        if (ViewState["lstTemplateRule"] != null)
            return ViewState["lstTemplateRule"] as List<ContractTemplateRule>;
        return null;
    }
    set { ViewState["lstTemplateRule"] = value; }
}

private List<ContractTemplateRule> LoadTemplateRule()
{
    if (this.lstTemplateRule != null)
        return this.lstTemplateRule;

    List<ContractTemplateRule> lstRule = null;
    string strJson = SYS_SettingService.GetStringValue("ContractTemplateRules");
    if (strJson != null && strJson.Trim() != "")
    {
        try
        {
            lstRule = JsonConvert.DeserializeObject<List<ContractTemplateRule>>(strJson);
        }
        catch (Exception)
        {
            lstRule = null;
        }
    }
    if (lstRule == null)
        lstRule = new List<ContractTemplateRule>();

    this.lstTemplateRule = lstRule;
    return this.lstTemplateRule;
}

private bool IsInRuleList(string strList, string strValue)
{
    if (strList == null || strList.Trim() == "")
        return true; // rỗng = áp dụng mọi giá trị

    string[] arrValue = strList.Split(',');
    for (int i = 0; i < arrValue.Length; i++)
    {
        if (arrValue[i].Trim() == strValue)
            return true;
    }
    return false;
}

private ContractTemplateRule GetTemplateRuleByCode(string strTemplateCode)
{
    List<ContractTemplateRule> lstRule = LoadTemplateRule();
    for (int i = 0; i < lstRule.Count; i++)
    {
        if (lstRule[i].code == strTemplateCode)
            return lstRule[i];
    }
    return null;
}

private string ResolveTemplateCode(int intOfficeId, string strSpecialBranchId)
{
    List<ContractTemplateRule> lstRule = LoadTemplateRule();
    for (int i = 0; i < lstRule.Count; i++)
    {
        ContractTemplateRule objRule = lstRule[i];
        if (objRule.code == "5") // mẫu thanh lý do người dùng tick chọn, không match tự động
            continue;
        if (!IsInRuleList(objRule.office, intOfficeId.ToString()))
            continue;
        if (!IsInRuleList(objRule.branch, strSpecialBranchId))
            continue;
        return objRule.code;
    }
    return "1";
}

#endregion

